  const T=window.NayadStaffTime;
  const state={tab:'employees',employees:[],attendance:[],settings:null,loading:false,wageType:'monthly',editing:null,publicData:null,timer:null,detailMonth:null,detailAttendance:[],schedules:[],lateRules:[],detailEmployee:null,timeRow:null,timeEmployee:null,timeLoading:false,timeRequest:0};
  const esc=value=>String(value??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
  const sb=()=>window.nayadSupabase;
  const store=()=>window.__nayadActiveStore||null;
  const storeId=()=>window.__nayadActiveStoreId||store()?.id||null;
  const number=value=>{const n=Number(String(value??'').replace(/[^0-9.]/g,''));return Number.isFinite(n)?n:0;};
  const money=value=>new Intl.NumberFormat('mn-MN',{maximumFractionDigits:0}).format(Number(value)||0)+' ₮';
  const duration=seconds=>{seconds=Math.max(0,Number(seconds)||0);const h=Math.floor(seconds/3600),m=Math.floor(seconds%3600/60);return h?`${h}ц${m?' '+m+'м':''}`:`${m} мин`;};
