  const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Ulaanbaatar'}).format(new Date());
  const attendanceSeconds=row=>row?.clock_in?Math.max(0,(new Date(row.clock_out||(row.work_date===today()?Date.now():row.clock_in))-new Date(row.clock_in))/1000):0;
  function validMonth(value){return /^\d{4}-(0[1-9]|1[0-2])$/.test(String(value||''))?String(value):today().slice(0,7);}
  function monthBounds(value){const month=validMonth(value),[year,number]=month.split('-').map(Number),next=number===12?`${year+1}-01`:`${year}-${String(number+1).padStart(2,'0')}`;return {month,start:`${month}-01`,end:`${next}-01`};}
  function moveMonth(value,offset){const [year,month]=validMonth(value).split('-').map(Number),date=new Date(Date.UTC(year,month-1+offset,1));return `${date.getUTCFullYear()}-${String(date.getUTCMonth()+1).padStart(2,'0')}`;}
  function workDateLabel(value){return value.slice(5).replace('-','/')+' · '+['Ням','Даваа','Мягмар','Лхагва','Пүрэв','Баасан','Бямба'][new Date(value+'T12:00:00+08:00').getUTCDay()];}
  function install(){if(!document.getElementById('nayad-staff-style'))document.head.insertAdjacentHTML('beforeend',STYLE);}
  function root(){let el=document.getElementById('staffRoot');if(!el){el=document.createElement('div');el.id='staffRoot';el.className='staffRoot';document.body.appendChild(el);}return el;}
