  async function open(){if(!window.__nayadCan?.('staff','edit'))return window.toast?.('Ажилтан удирдах эрхгүй байна.');document.getElementById('appPrintSheet')?.remove();if(!storeId())return window.toast?.('Дэлгүүрээ сонгоно уу.');install();document.body.classList.add('staffOpen');root().innerHTML=shell('<div class="staffEmpty">Ачаалж байна…</div>');await load();render();}
  function shell(body,title='Ажилтан, цалин',back='NayadStaff.close()'){return `<div class="staffShell"><div class="staffHead"><button type="button" onclick="${back}" aria-label="Буцах">←</button><h1>${esc(title)}</h1></div><div class="staffStore">${window.NayadApplications?.icon||''} ${esc(store()?.name||'Дэлгүүр')}</div>${body}</div>`;}
  async function load(){state.loading=true;try{const id=storeId(),start=today().slice(0,8)+'01';const [employees,attendance,settings,schedules,lateRules]=await Promise.all([sb().from('staff_employees').select('*').eq('store_id',id).eq('active',true).order('name'),sb().from('staff_attendance').select('*').eq('store_id',id).gte('work_date',start).order('work_date',{ascending:false}),sb().rpc('staff_ensure_settings',{p_store_id:id}),sb().from('staff_schedule_history').select('*').eq('store_id',id).order('effective_from',{ascending:false}),sb().from('staff_late_rules').select('*').eq('store_id',id)]);if(employees.error)throw employees.error;if(attendance.error)throw attendance.error;if(settings.error)throw settings.error;if(schedules.error)throw schedules.error;if(lateRules.error)throw lateRules.error;state.lateRules=lateRules.data||[];state.schedules=schedules.data||[];state.employees=employees.data||[];state.attendance=attendance.data||[];state.settings=settings.data||null;}catch(error){console.error('Staff load:',error);window.toast?.(error.message||'Ажилтны мэдээлэл ачаалсангүй.');}finally{state.loading=false;}}
  function tabs(){return `<div class="staffTabs">${[['employees','Ажилтан'],['time','Цаг'],['salary','Цалин'],['chat','Чат']].map(([key,label])=>`<button class="${state.tab===key?'active':''}" onclick="NayadStaff.tab('${key}')">${label}</button>`).join('')}</div>`;}
  function render(){const body=tabs()+(state.tab==='employees'?employeesView():state.tab==='time'?timeView():salaryView());root().innerHTML=shell(body);if(state.tab==='salary')window.NayadSalary?.list(state.employees);window.NayadHub?.hydrateAvatars();if(state.tab==='employees')window.NayadSelf?.statuses();}
  function employeesView(){return `<div id="staffProfileSummary"></div><div class="staffToolbar"><button class="primaryMini" onclick="NayadStaff.add()">＋ Ажилтан нэмэх</button><button onclick="NayadStaff.qr()">▦ QR код</button></div><button class="staffLocation" style="margin:0 0 12px" onclick="NayadApplications.list()">Ирсэн анкетууд →</button>${state.employees.length?state.employees.map(e=>`<div class="staffCard"><div class="staffRow"><div class="staffAvatar" data-employee="${e.id}">${esc(e.name.slice(0,1).toUpperCase())}</div><div class="staffMeta"><b>${esc(e.name)}</b><small>${esc(e.phone)} · ${e.wage_type==='hourly'?money(e.hourly_rate)+'/цаг':money(e.monthly_salary)+'/сар'}</small></div><button class="staffEdit" onclick="NayadStaff.edit('${e.id}')" aria-label="Засах">✎</button></div><div class="selfStatus" data-profile-status="${e.id}"></div></div>`).join(''):'<div class="staffEmpty">Ажилтан бүртгэгдээгүй байна.</div>'}`;}
  function attendanceFor(employee,date=today()){return state.attendance.find(a=>a.employee_id===employee.id&&a.work_date===date);}
  function timeView(){const rows=state.employees.map(e=>{const a=attendanceFor(e),working=a?.clock_in&&!a?.clock_out;return `<div class="staffTimeRow" data-staff-name="${esc(e.name)}"><div class="staffTimePerson"><div class="staffAvatar" data-employee="${e.id}">${esc(e.name.slice(0,1))}</div><div><b>${esc(e.name)}</b><small class="${working?'working':''}">${working?'Ажиллаж байна':a?.clock_out?(a.approval_status==='approved'?'Баталсан':'Хүлээгдэж буй'):'Бүртгэлгүй'}</small></div></div><b>${time(a?.clock_in)}</b><b>${time(a?.clock_out)}</b><b>${a?.clock_in?duration((new Date(a.clock_out||Date.now())-new Date(a.clock_in))/1000):'—'}</b><button class="staffEdit" onclick="NayadStaff.editTime('${e.id}')" aria-label="Цаг засах">${a?'✎':'＋'}</button></div>`}).join('');const arrived=state.employees.filter(e=>attendanceFor(e)?.clock_in).length;return `<input class="staffSearch" placeholder="Ажилтан хайх" oninput="NayadStaff.search(this.value)"><div class="staffSummary">${state.employees.length} ажилтан · ${arrived} ирсэн · ${state.employees.length-arrived} бүртгэлгүй</div><div class="staffTimeRow staffTimeLabels"><span></span><span>Ирсэн</span><span>Гарсан</span><span>Ажилласан</span><span></span></div><div id="staffTimeRows">${rows||'<div class="staffEmpty">Ажилтан бүртгэгдээгүй байна.</div>'}</div>`;}
  function salaryView(){return '<div id="staffSalaryContent"><div class="staffEmpty">Цалин ачаалж байна…</div></div>'; }
  function legacySalaryView(){return `<div class="staffSummary">Баталсан цагаар бодсон дүн · Ажилтан дээр дарж өдрөөр харна.</div>${state.employees.map(e=>{const rows=state.attendance.filter(a=>a.employee_id===e.id),approved=rows.filter(a=>a.approval_status==='approved'),seconds=approved.reduce((n,a)=>n+(a.approved_seconds||0),0),pay=approved.reduce((n,a)=>n+T.pay(a),0);return `<button class="staffCard staffSalaryCard" onclick="NayadStaff.detail('${e.id}')"><div class="staffSalaryHeader"><div class="staffAvatar" data-employee="${e.id}">${esc(e.name.slice(0,1))}</div><b class="staffSalaryName">${esc(e.name)}</b><span class="staffChevron" aria-hidden="true">›</span></div><div class="staffSalaryStatus"><span>Баталсан ${duration(seconds)}</span><span>Хүлээгдэж буй ${rows.length-approved.length}</span></div><div class="staffSalaryPayday">${esc(payLabel(e.pay_days))}</div>${deductionRows(approved)?`<div class="staffHint">Хоцролтын суутгал: −${money(deductionRows(approved))}</div>`:''}<div class="staffSalaryTotal"><small>${e.wage_type==='hourly'?'Баталсан цагийн дүн':'Тохирсон сарын цалин'}</small><strong>${e.wage_type==='hourly'?money(Math.max(0,pay-deductionRows(approved))):money(Math.max(0,e.monthly_salary-deductionRows(approved)))}</strong></div></button>`}).join('')||'<div class="staffEmpty">Цалин бодох ажилтан алга.</div>'}`;}
  function payLabel(days){return days?.length?'Сар бүр '+days.map(d=>d===0?'сарын сүүл':d+'-нд').join(', '):'Цалин олгох өдөр тохируулаагүй';}
  async function detail(employeeId,month=state.detailMonth||today().slice(0,7)){const employee=state.employees.find(item=>item.id===employeeId);if(!employee)return;const bounds=monthBounds(month);state.detailMonth=bounds.month;state.detailEmployee=employeeId;root().innerHTML=shell(`<div class="staffEmpty">Цагийн бүртгэл ачаалж байна…</div>`,'Ажилласан цаг','NayadStaff.detailBack()');try{const {data,error}=await sb().from('staff_attendance').select('*').eq('store_id',storeId()).eq('employee_id',employeeId).gte('work_date',bounds.start).lt('work_date',bounds.end).order('work_date',{ascending:false});if(error)throw error;state.detailAttendance=data||[];renderDetail(employee);}catch(error){root().innerHTML=shell(`<div class="staffError">${esc(error.message||'Цагийн бүртгэл ачаалсангүй.')}</div><button class="staffSave" onclick="NayadStaff.detail('${employeeId}','${bounds.month}')">ДАХИН ОРОЛДОХ</button>`,'Ажилласан цаг','NayadStaff.detailBack()');}}
  function detailBack(){state.detailEmployee=null;state.tab='salary';render();}
  function renderDetail(employee){const rows=state.detailAttendance.filter(r=>r.clock_in),approved=rows.filter(r=>r.approval_status==='approved'),seconds=approved.reduce((n,r)=>n+(r.approved_seconds||0),0);root().innerHTML=shell(`<div class="staffDetailTitle"><div class="staffAvatar" data-employee="${employee.id}">${esc(employee.name.slice(0,1))}</div><h2>${esc(employee.name)}</h2></div><button class="staffPaydayLink" onclick="NayadStaff.editPayDays('${employee.id}')"><span><small>Цалин буух өдөр</small><b>${esc(employee.pay_days?.length?payLabel(employee.pay_days):'Өдөр тохируулах')}</b></span><span aria-hidden="true">›</span></button><div class="staffMonthNav"><button onclick="NayadStaff.detail('${employee.id}','${moveMonth(state.detailMonth,-1)}')">‹</button><label class="staffMonthPick">${state.detailMonth.slice(0,4)} оны ${Number(state.detailMonth.slice(5))} сар<input type="month" value="${state.detailMonth}" onchange="NayadStaff.detail('${employee.id}',this.value)" aria-label="Сар сонгох"></label><button onclick="NayadStaff.detail('${employee.id}','${moveMonth(state.detailMonth,1)}')">›</button></div><div class="staffDetailOverview"><div class="staffDetailSummary"><div><small>Цалин бодох цаг</small><b>${duration(seconds)}</b></div><div><small>Хүлээгдэж буй</small><b>${rows.length-approved.length} өдөр</b></div><div><small>Ажилласан өдөр</small><b>${approved.length} өдөр</b></div><div><small>${employee.wage_type==='hourly'?'Цагийн цалин':'Тохирсон сарын цалин'}</small><b>${money(Math.max(0,(employee.wage_type==='hourly'?approved.reduce((n,r)=>n+T.pay(r),0):employee.monthly_salary)-deductionRows(approved)))}</b></div></div><button class="staffAddTime" onclick="NayadStaff.editTime('${employee.id}','')"><span aria-hidden="true">+</span><small>Цаг нэмэх</small></button></div>${deductionRows(approved)?`<p class="staffHint">Хоцролтын суутгал: −${money(deductionRows(approved))}</p>`:''}${rows.map(r=>`<div class="staffCompactDay"><div class="staffCompactDayTop"><b>${esc(workDateLabel(r.work_date))}</b><span aria-label="Ирсэн, гарсан цаг · Ажилласан хугацаа">${time(r.clock_in)} – ${time(r.clock_out)} · ${r.clock_out?duration((new Date(r.clock_out)-new Date(r.clock_in))/1000):'—'}${r.clock_out&&new Date(r.clock_out)-new Date(r.clock_in)>0&&localTimeValue(r.clock_out)<localTimeValue(r.clock_in)?'<small>Дараа өдөр</small>':''}</span></div><div class="staffCompactDayBottom"><span class="staffApprovalIcon ${r.approval_status==='approved'?'approved':'pending'}" aria-hidden="true">${r.approval_status==='approved'?'✓':'◷'}</span><span class="staffCompactStatus">${r.approval_status==='approved'?`Цалин бодох цаг: ${duration(r.approved_seconds)} · Илүү цаг: ${duration(r.overtime_seconds)}`:r.clock_out?'Батлах хүлээгдэж байна':'Гарсан цаг дутуу'}</span><button class="staffCompactEdit" aria-label="${r.approval_status==='approved'?'Цаг засах':'Шалгаж батлах'}" title="${r.approval_status==='approved'?'Цаг засах':'Шалгаж батлах'}" onclick="NayadStaff.editTime('${employee.id}','${r.work_date}')"><svg viewBox="0 0 24 24" width="19" height="19" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m16 3 5 5-13 13H3v-5Z M14 5l5 5"/></svg></button></div>${T.deduction(r)?`<p class="staffHint">Хоцролтын суутгал: −${money(T.deduction(r))}</p>`:''}${r.edit_note?`<p class="staffHint">${esc(r.edit_note)}</p>`:''}</div>`).join('')||'<div class="staffEmpty">Энэ сард бүртгэл алга.</div>'}<p class="staffHint">Цагийн цалинг зөвхөн эзний баталсан цагаар тооцно.</p>`,'Ажилласан цаг','NayadStaff.detailBack()');window.NayadHub?.hydrateAvatars();}
  function tab(value){window.NayadHub?.stop();if(value==='chat')return window.NayadHub.list();state.tab=value;render();}
  function search(query){const q=String(query||'').toLowerCase();document.querySelectorAll('#staffTimeRows .staffTimeRow').forEach(card=>card.classList.toggle('hideStaff',!card.textContent.toLowerCase().includes(q)));}
  function tempPin(){return String(crypto.getRandomValues(new Uint32Array(1))[0]%1000000).padStart(6,'0');}
  function add(){state.editing=null;state.wageType='monthly';form();}
  function editPayDays(id){edit(id);document.getElementById('staffSalarySection').open=true;document.getElementById('staffPaydayHeading')?.scrollIntoView({block:'start'});}
  function edit(id){state.editing=state.employees.find(e=>e.id===id)||null;state.wageType=state.editing?.wage_type||'monthly';form();}
  function form(){const e=state.editing,pin=e?'':tempPin(),h=state.schedules.filter(h=>h.employee_id===e?.id).sort((a,b)=>b.effective_from.localeCompare(a.effective_from)||b.created_at.localeCompare(a.created_at))[0];state.formSession=Symbol();state.pendingImages=[];state.removedImages=[];state.existingMedia=[];state.mediaBusy=false;const late=T.schedule(state.lateRules,e?.id,'9999-12-31')?.rule||lateDefault();root().innerHTML=shell(`<div class="staffForm"><details class="staffSection" open><summary>1. Ажилтны бүртгэл</summary><div class="staffSectionBody">${mediaFields()}<label>Ажилтны нэр *</label><input id="staffName" value="${esc(e?.name||'')}"><label>Утасны дугаар *</label><input id="staffPhone" inputmode="numeric" maxlength="8" value="${esc(e?.phone||'')}"><label>${e?'Шинэ PIN · өөрчлөхгүй бол хоосон':'Түр PIN · 6 орон *'}</label><input id="staffPin" inputmode="numeric" maxlength="6" value="${esc(pin)}"></div></details><details class="staffSection" id="staffSalarySection"><summary>2. Ажиллах цаг, цалин</summary><div class="staffSectionBody"><h3>Ажиллах цаг</h3><div class="staffSplit"><div><label>Эхлэх</label><input id="staffStart" type="time" value="${h?.start_time?.slice(0,5)||'09:00'}"></div><div><label>Дуусах</label><input id="staffEnd" type="time" value="${h?.end_time?.slice(0,5)||'18:00'}"></div></div><label>Хэзээнээс мөрдөх</label><input id="staffEffective" type="date" value="${h?.effective_from||today()}"><p class="staffHint">Хүссэн үедээ өөрчилж болно. Өмнө баталсан цаг өөрчлөгдөхгүй.</p><h3>Цалингийн тохиргоо</h3><div class="staffWageSwitch"><button class="${state.wageType==='monthly'?'active':''}" onclick="NayadStaff.wage('monthly')">Сарын цалин</button><button class="${state.wageType==='hourly'?'active':''}" onclick="NayadStaff.wage('hourly')">Цагийн цалин</button></div><div id="staffWageFields">${wageFields(e)}</div>${window.NayadSalary?.bankFields("staffBank")||''}<h3 id="staffPaydayHeading">Цалин буух өдөр</h3><div class="staffPayChoices">${[1,2,3].map(n=>`<button type="button" onclick="NayadStaff.payCount(${n})">${n===3?'Бусад':n+' удаа'}</button>`).join('')}</div><label>Сард олгох тоо</label><input id="staffPayCount" type="number" min="1" max="31" value="${e?.pay_days?.length||1}" onchange="NayadStaff.payCount(this.value)"><div id="staffPayDays">${payFields(e?.pay_days?.length?e.pay_days:[0])}</div><div class="staffCalc" id="staffPaySummary">${payLabel(e?.pay_days?.length?e.pay_days:[0])}</div><button id="staffLocationButton" class="staffLocation" onclick="NayadStaff.location()">⌖ Дэлгүүрийн байршил<span>${state.settings?.latitude==null?'Тохируулаагүй':'Тохируулсан'}</span></button></div></details>${section("staffResponsibility","3. Хариуцлага",lateFields(late))}${section("staffDutySection","4. Ажлын чиг үүрэг",dutyFields(e))}${e?`<button class="staffLocation" onclick="NayadHub.deactivate('${e.id}')">Ажилтны хандалтыг хаах</button>`:''}<button id="staffSave" class="staffSave" onclick="NayadStaff.save()">${e?'ӨӨРЧЛӨЛТ ХАДГАЛАХ':'АЖИЛТАН НЭМЭХ'}</button></div>`,e?'Ажилтан засах':'Ажилтан нэмэх');(e?.duties?.length?e.duties:['']).forEach(addDuty);latePreview();loadMedia(e,state.formSession);window.NayadSalary?.initBank(e?.id);}
  function wageFields(e){return state.wageType==='monthly'?`<label>Сарын цалин *</label><input id="staffMonthly" inputmode="decimal" value="${esc(e?.monthly_salary??'')}">`:`<label>Нэг цагт олгох цалин (₮) *</label><input id="staffHourly" inputmode="decimal" value="${esc(e?.hourly_rate??'')}" oninput="NayadStaff.calc()"><label>Илүү цагийн хөлс</label><select id="staffOvertime" onchange="NayadStaff.calc()">${[1,1.5,2].map(n=>`<option value="${n}" ${Number(e?.overtime_multiplier||1.5)===n?'selected':''}>${n===1?'Энгийн үнээр':n+' дахин'}</option>`).join('')}</select><div id="staffOvertimeHint" class="staffHint">${overtimeHint(e?.hourly_rate,e?.overtime_multiplier||1.5)}</div>`;}
  function payFields(days){return days.map((d,i)=>`<label>${i+1}-р олголт</label><select class="staffPayDay" onchange="NayadStaff.paySummary()">${[...Array(31)].map((_,j)=>`<option value="${j+1}" ${d===j+1?'selected':''}>${j+1}-нд</option>`).join('')}<option value="0" ${d===0?'selected':''}>Сарын сүүлийн өдөр</option></select>`).join('');}
  function payCount(value){const n=Math.min(31,Math.max(1,Number(value)||1)),old=[...document.querySelectorAll('.staffPayDay')].map(el=>Number(el.value));document.getElementById('staffPayCount').value=n;document.getElementById('staffPayDays').innerHTML=payFields(Array.from({length:n},(_,i)=>old[i]??Math.min(31,(i+1)*5)));paySummary();}
  function paySummary(){const days=[...document.querySelectorAll('.staffPayDay')].map(el=>Number(el.value));document.getElementById('staffPaySummary').textContent=payLabel(days)+' · Богино сард сарын сүүлийн өдөрт таарна.';}
  function wage(type){state.wageType=type;document.getElementById('staffWageFields').innerHTML=wageFields(state.editing);document.querySelectorAll('.staffWageSwitch button').forEach((b,i)=>b.classList.toggle('active',(i===0)===(type==='monthly')));}
  function overtimeHint(rate,multiplier){const amount=Number(rate)||8000;return `Жишээ: үндсэн цаг ${money(amount)} бол илүү цаг ${money(amount*Number(multiplier))}.`;}
  function calc(){const hint=document.getElementById('staffOvertimeHint');if(hint)hint.textContent=overtimeHint(number(document.getElementById('staffHourly')?.value),document.getElementById('staffOvertime')?.value||1.5);const rate=number(document.getElementById('staffHourly')?.value);const out=document.getElementById('staffExample');if(out)out.textContent=`168 цаг × ${money(rate)} = ${money(168*rate)}`;}
  async function saveEmployee(){const button=document.getElementById('staffSave');button.disabled=true;try{const val=id=>document.getElementById(id)?.value,e=state.editing;const payload={id:e?.id||null,updated_at:e?.updated_at||null,name:val('staffName').trim(),phone:val('staffPhone'),pin:val('staffPin'),wage_type:state.wageType,monthly_salary:state.wageType==='monthly'?number(val('staffMonthly')):null,hourly_rate:state.wageType==='hourly'?number(val('staffHourly')):null,overtime_multiplier:state.wageType==='hourly'?number(val('staffOvertime')):e?.overtime_multiplier||1.5,weekly_days:e?.weekly_days||6,start_time:val('staffStart'),end_time:val('staffEnd'),effective_from:val('staffEffective'),pay_days:[...document.querySelectorAll('.staffPayDay')].map(el=>Number(el.value))};if(!T.span(payload.start_time,payload.end_time))throw Error('Ажиллах цагийг зөв оруулна уу.');if(!(state.wageType==='monthly'?val('staffMonthly'):val('staffHourly'))?.trim())throw Error('Цалингийн дүнг оруулна уу.');Object.assign(payload,extraEmployeePayload());if(window.NayadSalary)payload.bank_details=window.NayadSalary.bankPayload();payload.application_id=button.dataset.applicationId||null;const {error}=await sb().rpc('staff_save_employee_v5',{p_store_id:storeId(),p_employee:payload});if(error)throw error;await load();state.tab='employees';render();window.toast?.('Ажилтан хадгалагдлаа.');}catch(error){window.toast?.(error.message||'Ажилтан хадгалсангүй.');}finally{button.disabled=false;}}
  function section(id,title,body,open=false){return `<details class="staffSection" id="${id}" ${open?'open':''}><summary>${title}</summary><div class="staffSectionBody">${body}</div></details>`;}
  const lateDefault=()=>({enabled:false,grace:0,interval:5,amount:0,basis:'excess',rounding:'floor',cap:null,effective_from:today()});
  function lateFields(r){return `<label class="staffCheck"><input id="lateEnabled" type="checkbox" ${r.enabled?'checked':''} onchange="NayadStaff.latePreview()">Хоцролтын суутгал тооцох</label><div id="lateOptions"><div class="staffSplit"><div><label>Хүлцэх минут</label><input id="lateGrace" type="number" min="0" max="1440" value="${r.grace}" oninput="NayadStaff.latePreview()"></div><div><label>Хэдэн минут тутам</label><input id="lateInterval" type="number" min="1" max="1440" value="${r.interval}" oninput="NayadStaff.latePreview()"></div></div><label>Тутамд суутгах дүн (₮)</label><input id="lateAmount" type="number" min="0" max="100000000" value="${r.amount}" oninput="NayadStaff.latePreview()"><label>Тооцох минут</label><select id="lateBasis" onchange="NayadStaff.latePreview()"><option value="excess" ${r.basis==='excess'?'selected':''}>Хүлцэх минутаас хэтэрсэн хэсэг</option><option value="all" ${r.basis==='all'?'selected':''}>Хүлцэх минут хэтэрвэл нийт хоцролт</option></select><label>Бүтэн хүрээгүй интервалыг</label><select id="lateRounding" onchange="NayadStaff.latePreview()"><option value="floor" ${r.rounding==='floor'?'selected':''}>Тооцохгүй</option><option value="ceil" ${r.rounding==='ceil'?'selected':''}>Нэг бүтэн интервалд тооцно</option></select><label>Өдрийн дээд суутгал (₮)</label><input id="lateCap" type="number" min="0" max="100000000" placeholder="Хоосон бол хязгааргүй" value="${r.cap??''}" oninput="NayadStaff.latePreview()"></div><label>Хэзээнээс мөрдөх</label><input id="lateEffective" type="date" value="${esc(r.effective_from)}"><div id="lateExample" class="staffCalc"></div><p class="staffHint">Цаг батлахдаа суутгалыг шалгаж, шалтгаантайгаар өөрчлөх эсвэл чөлөөлж болно. Өмнө баталсан тооцоо хэвээр үлдэнэ.</p>`;}
  function readLate(){const v=id=>document.getElementById(id).value;return {enabled:document.getElementById('lateEnabled').checked,grace:Number(v('lateGrace')),interval:Number(v('lateInterval')),amount:Number(v('lateAmount')),basis:v('lateBasis'),rounding:v('lateRounding'),cap:v('lateCap')===''?null:Number(v('lateCap')),effective_from:v('lateEffective')};}
  function latePreview(){const r=readLate();document.getElementById('lateOptions').hidden=!r.enabled;document.getElementById('lateExample').textContent=r.enabled?`Жишээ: 17 минут хоцорвол ${money(T.lateAmount(r,17))} суутгана.`:'Хоцролтын суутгал тооцохгүй.';}
  function dutyFields(e){return `<label>Албан тушаал</label><input id="staffJobTitle" maxlength="120" value="${esc(e?.job_title||'')}" placeholder="Жишээ: Худалдагч"><label>Хариуцах ажлууд</label><div id="staffDuties"></div><button type="button" class="staffLocation" onclick="NayadStaff.addDuty()">＋ Үүрэг нэмэх</button><label>Нэмэлт тайлбар</label><textarea id="staffDutyNotes" rows="3" maxlength="4000">${esc(e?.duty_notes||'')}</textarea>`;}
  function addDuty(value=''){const box=document.getElementById('staffDuties');if(box.children.length>=50)return;const row=document.createElement('div');row.className='staffDutyRow';row.innerHTML=`<input class="staffDuty" maxlength="500" placeholder="Ажлын чиг үүрэг" value="${esc(value)}"><button type="button" aria-label="Үүрэг хасах">×</button>`;row.querySelector('button').onclick=()=>row.remove();box.append(row);}
  function mediaFields(){return `<div class="staffMediaGrid">${[['avatar','Цээж зураг'],['id_front','Үнэмлэх · урд'],['id_back','Үнэмлэх · ар'],['reference','Нэмэлт баримт']].map(([k,label])=>`<div><label>${label}</label><div class="staffMediaItems" id="media-${k}"></div><label class="staffMediaPick">＋ Зураг оруулах<input type="file" accept="image/*" ${k==='reference'?'multiple':''} onchange="NayadStaff.pickMedia('${k}',this)"></label></div>`).join('')}</div><p class="staffHint">Баримтын зургийг зөвхөн ажилтан болон дэлгүүрийн эзэн үзнэ.</p>`;}
  async function mediaApi(action,payload){const {data,error}=await sb().rpc('staff_hub',{p_action:action,p_payload:payload,p_store_id:storeId(),p_store_token:null,p_device_token:null});if(error||data?.error)throw Error(error?.message||data.error);return data;}
  async function loadMedia(e,session){if(!e)return;try{const d=await mediaApi('profile',{employee:'e:'+e.id});if(state.formSession!==session)return;state.existingMedia=d.media||[];renderMedia();}catch(error){window.toast?.('Баримт ачаалсангүй: '+error.message);}}
  function renderMedia(){for(const k of ['avatar','id_front','id_back','reference']){const box=document.getElementById('media-'+k);if(!box)continue;box.replaceChildren();const pending=state.pendingImages.filter(m=>m.kind===k),items=[...state.existingMedia.filter(m=>m.kind===k&&!state.removedImages.includes(m.id)&&!(k!=='reference'&&pending.length)),...pending];for(const m of items){const tile=document.createElement('div');tile.className='staffMediaTile';const view=document.createElement('button');view.type='button';view.className='staffMediaView';view.setAttribute('aria-label','Зураг харах');view.textContent='▧ Зураг';if(m.image){view.innerHTML='<img alt="Сонгосон зураг">';view.firstChild.src=m.image;}view.onclick=()=>m.id?window.NayadHub.viewImage(m.id):previewImage(m.image);const remove=document.createElement('button');remove.type='button';remove.textContent='×';remove.setAttribute('aria-label','Зураг хасах');remove.onclick=()=>{if(m.id)state.removedImages.push(m.id);else state.pendingImages=state.pendingImages.filter(x=>x!==m);renderMedia();};tile.append(view,remove);box.append(tile);}}}
  function previewImage(src){const d=document.createElement('dialog');d.className='staffImageDialog';const x=document.createElement('button');x.textContent='×';x.onclick=()=>d.close();const img=document.createElement('img');img.src=src;img.alt='Зургийн урьдчилсан харагдац';d.append(x,img);d.onclick=e=>{if(e.target===d)d.close();};d.onclose=()=>d.remove();document.body.append(d);d.showModal();}
  async function compressMedia(file){if(!file.type.startsWith('image/')||file.size>25*1024*1024)throw Error('25 MB хүртэл хэмжээтэй зураг сонгоно уу.');const url=URL.createObjectURL(file);try{const img=new Image();img.src=url;await img.decode();const scale=Math.min(1,1400/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);let quality=.82,result=canvas.toDataURL('image/jpeg',quality);while(result.length>1400000&&quality>.25){quality-=.1;result=canvas.toDataURL('image/jpeg',quality);}if(result.length>1400000)throw Error('Зургийн хэмжээ их байна. Жижиг зураг сонгоно уу.');return result;}finally{URL.revokeObjectURL(url);}}
  async function pickMedia(kind,input){if(state.mediaBusy)return;const session=state.formSession;state.mediaBusy=true;document.querySelectorAll('.staffMediaPick input').forEach(i=>i.disabled=true);document.getElementById('staffSave').disabled=true;try{for(const file of input.files){const image=await compressMedia(file);if(session!==state.formSession)return;if(kind!=='reference')state.pendingImages=state.pendingImages.filter(m=>m.kind!==kind);if(state.pendingImages.length>=20)throw Error('Нэг хадгалалтаар 20 хүртэл зураг оруулна.');state.pendingImages.push({kind,image});}renderMedia();}catch(error){window.toast?.(error.message);}finally{if(session===state.formSession){state.mediaBusy=false;document.querySelectorAll('.staffMediaPick input').forEach(i=>i.disabled=false);document.getElementById('staffSave').disabled=false;input.value='';}}}
  function extraEmployeePayload(){if(state.mediaBusy)throw Error('Зураг бэлдэж байна. Түр хүлээнэ үү.');const r=readLate();if(!Number.isInteger(r.grace)||r.grace<0||r.grace>1440||!Number.isInteger(r.interval)||r.interval<1||r.interval>1440||!Number.isFinite(r.amount)||r.amount<0||r.amount>100000000||r.cap!==null&&(!Number.isFinite(r.cap)||r.cap<0||r.cap>100000000)||!r.effective_from)throw Error('Хоцролтын тохиргоог зөв оруулна уу.');return {late_rule:r,job_title:document.getElementById('staffJobTitle').value.trim(),duties:[...document.querySelectorAll('.staffDuty')].map(x=>x.value.trim()).filter(Boolean),duty_notes:document.getElementById('staffDutyNotes').value,images:state.pendingImages,image_removals:state.removedImages};}
  function deductionRows(rows){return rows.reduce((n,r)=>n+T.deduction(r),0);}
  function deductionPreview(){const e=state.timeEmployee,date=document.getElementById('staffAttendanceDate').value,row=state.timeRow,h=T.schedule(state.schedules,e.id,date),rule=row?.approval_status==='approved'?(row.wage_snapshot?.late_rule||{}):(T.schedule(state.lateRules,e.id,date)?.rule||{}),start=row?.schedule_snapshot?.start||h?.start_time,mins=Math.max(0,T.minutes(document.getElementById('staffAttendanceIn').value)-T.minutes(start))||0;return {mins,amount:T.lateAmount(rule,mins)};}
  function deductionCalc(){const d=deductionPreview();document.getElementById('staffLateCalc').textContent=`Хоцролт: ${d.mins} мин · Суутгал: ${money(d.amount)}`;document.getElementById('staffOverrideFields').hidden=!document.getElementById('staffOverride').checked;}

  function position(){return new Promise((resolve,reject)=>navigator.geolocation.getCurrentPosition(resolve,reject,{enableHighAccuracy:true,timeout:15000,maximumAge:0}));}
  async function setLocation(){try{const p=await position();const {data,error}=await sb().rpc('staff_set_location',{p_store_id:storeId(),p_lat:p.coords.latitude,p_lng:p.coords.longitude,p_radius_m:150});if(error)throw error;state.settings=data;window.toast?.('Дэлгүүрийн байршил хадгалагдлаа.');const hint=document.querySelector('#staffLocationButton span');if(hint)hint.textContent='Тохируулсан';}catch(error){window.toast?.(error.message||'Байршил тогтоосонгүй.');}}
  function localTimeValue(value){if(!value)return '';return new Intl.DateTimeFormat('en-GB',{hour:'2-digit',minute:'2-digit',hour12:false,timeZone:'Asia/Ulaanbaatar'}).format(new Date(value));}
  async function editTime(employeeId,date=today()){const e=state.employees.find(e=>e.id===employeeId);if(!e)return;state.timeEmployee=e;state.timeRow=null;root().innerHTML=shell(`<div class="staffForm"><h2>${esc(e.name)}</h2><label>Огноо</label><input id="staffAttendanceDate" type="date" max="${today()}" value="${date||today()}" onchange="NayadStaff.loadTime()"><div class="staffSplit"><div><label>Ирсэн цаг</label><input id="staffAttendanceIn" type="time" oninput="NayadStaff.timeCalc()"></div><div><label>Гарсан цаг</label><input id="staffAttendanceOut" type="time" oninput="NayadStaff.timeCalc()"></div></div><div id="staffTimeCalc" class="staffCalc"></div><label class="staffCheck"><input type="checkbox" id="staffApproveOvertime" onchange="NayadStaff.timeCalc()">Хуваариас давсан цагийг илүү цагт тооцох</label><div id="staffLateCalc" class="staffCalc"></div><label class="staffCheck"><input type="checkbox" id="staffOverride" onchange="NayadStaff.deductionCalc()">Суутгалыг өөрчлөх / чөлөөлөх</label><div id="staffOverrideFields" hidden><label>Суутгах дүн (₮) · чөлөөлөх бол 0</label><input id="staffOverrideAmount" type="number" min="0" max="100000000"><label>Өөрчлөх шалтгаан *</label><input id="staffOverrideReason" maxlength="1000"></div><label>Тайлбар</label><input id="staffAttendanceNote"><p class="staffHint">Эзний баталсан цаг эцсийн тооцоонд орно.</p><button id="staffTimeSave" class="staffSave" onclick="NayadStaff.saveTime('${employeeId}')">Хадгалж батлах</button></div>`,'Цаг бүртгэх','NayadStaff.timeBack()');await loadTime();}
  function timeBack(){if(state.detailEmployee)detail(state.detailEmployee);else render();}
  async function loadTime(){const request=++state.timeRequest,date=document.getElementById('staffAttendanceDate').value,e=state.timeEmployee;state.timeLoading=true;document.getElementById('staffTimeSave').disabled=true;try{const {data,error}=await sb().from('staff_attendance').select('*').eq('store_id',storeId()).eq('employee_id',e.id).eq('work_date',date).maybeSingle();if(request!==state.timeRequest||!document.getElementById('staffAttendanceDate'))return;if(error)throw error;state.timeRow=data;const h=T.schedule(state.schedules,e.id,date);document.getElementById('staffAttendanceIn').value=localTimeValue(data?.clock_in)||h?.start_time?.slice(0,5)||'';document.getElementById('staffAttendanceOut').value=localTimeValue(data?.clock_out)||(!data?h?.end_time?.slice(0,5):'')||'';document.getElementById('staffAttendanceNote').value=data?.edit_note||'';document.getElementById('staffApproveOvertime').checked=Boolean(data?.overtime_seconds);document.getElementById('staffOverride').checked=Boolean(data?.wage_snapshot?.late_reason);document.getElementById('staffOverrideAmount').value=data?.wage_snapshot?.late_deduction??0;document.getElementById('staffOverrideReason').value=data?.wage_snapshot?.late_reason||'';state.timeLoading=false;document.getElementById('staffTimeSave').disabled=false;timeCalc();}catch(error){if(request===state.timeRequest){document.getElementById('staffTimeCalc').textContent=error.message||'Бүртгэл ачаалсангүй. Огноогоо дахин сонгоно уу.';}}}
  function timeCalc(){const e=state.timeEmployee,date=document.getElementById('staffAttendanceDate').value,shift=T.shift(date,document.getElementById('staffAttendanceIn').value,document.getElementById('staffAttendanceOut').value),h=T.schedule(state.schedules,e.id,date),scheduled=state.timeRow?.schedule_snapshot?.seconds??(h?T.span(h.start_time,h.end_time):e.daily_hours*3600),extra=shift?Math.max(0,shift.seconds-scheduled):0;document.getElementById('staffTimeCalc').innerHTML=shift?`<small>${date.slice(5).replace('-','.')} ${localTimeValue(shift.from)} → ${new Intl.DateTimeFormat('en-CA',{month:'2-digit',day:'2-digit',timeZone:'Asia/Ulaanbaatar'}).format(shift.to)} ${localTimeValue(shift.to)}</small><p>Нийт ажилласан <b>${duration(shift.seconds)}</b></p><small>Хуваариас давсан: ${duration(extra)} · Батлах: ${duration(shift.seconds-(document.getElementById('staffApproveOvertime').checked?0:extra))}</small>`:'Ирсэн, гарсан цагийг оруулна уу.';deductionCalc();}
  async function history(id){root().innerHTML=shell('<div class="staffEmpty">Ачаалж байна…</div>','Цагийн түүх','NayadStaff.timeBack()');try{const {data,error}=await sb().from('staff_attendance_history').select('*').eq('store_id',storeId()).eq('attendance_id',id).order('changed_at',{ascending:false});if(error)throw error;root().innerHTML=shell((data||[]).map(h=>`<div class="staffCard staffHistory"><b>${h.after_value.approval_status==='approved'?'Эзэн баталсан / зассан':'Ажилтны бүртгэл'}</b><div>${esc(new Date(h.changed_at).toLocaleString('mn-MN',{timeZone:'Asia/Ulaanbaatar'}))}</div><div>${time(h.after_value.clock_in)} → ${time(h.after_value.clock_out)}</div>${h.before_value?`<small>Өмнө: ${time(h.before_value.clock_in)} → ${time(h.before_value.clock_out)}</small>`:''}<div>${esc(h.after_value.edit_note||'')}</div></div>`).join('')||'<div class="staffEmpty">Шинэчлэлтээс өмнөх бүртгэлд засварын түүх байхгүй.</div>','Цагийн түүх','NayadStaff.timeBack()');}catch(e){root().innerHTML=shell(`<div class="staffError">${esc(e.message)}</div>`,'Цагийн түүх','NayadStaff.timeBack()');}}
  async function saveTime(employeeId){const button=document.getElementById('staffTimeSave');if(state.timeLoading||button.disabled)return;button.disabled=true;try{const {error}=await sb().rpc('staff_review_attendance_v2',{p_store_id:storeId(),p_employee_id:employeeId,p_work_date:document.getElementById('staffAttendanceDate').value,p_clock_in:document.getElementById('staffAttendanceIn').value||null,p_clock_out:document.getElementById('staffAttendanceOut').value||null,p_note:document.getElementById('staffAttendanceNote').value,p_overtime:document.getElementById('staffApproveOvertime').checked,p_expected_updated_at:state.timeRow?.updated_at||null,p_deduction:document.getElementById('staffOverride').checked?Number(document.getElementById('staffOverrideAmount').value):null,p_deduction_reason:document.getElementById('staffOverride').checked?document.getElementById('staffOverrideReason').value:null});if(error)throw error;await load();await detail(employeeId,document.getElementById('staffAttendanceDate').value.slice(0,7));window.toast?.('Цаг батлагдлаа.');}catch(error){window.toast?.(error.message||'Цаг хадгалсангүй.');}finally{button.disabled=false;}}
  async function qr(){if(!state.settings?.attendance_token){await load();}const token=state.settings?.attendance_token;if(!token)return window.toast?.('QR код үүсгэсэнгүй.');const url=`${location.origin}${location.pathname}?tsag=${encodeURIComponent(token)}`;let code='';try{const qr=window.qrcode(0,'M');qr.addData(url);qr.make();code=qr.createSvgTag(5,2);}catch(error){console.error(error);}if(!code)return window.toast?.('QR код үүссэнгүй.');window.NayadApplications.qr(code,store()?.name||'Дэлгүүр');}

  function isAttendanceRoute(){return Boolean(new URLSearchParams(location.search).get('tsag'));}
  function publicKey(token){return `NAYAD_STAFF_DEVICE:${token}`;}
  async function initPublic(attendance=false){if(!isAttendanceRoute())return false;install();document.documentElement.dataset.nayadAttendance='1';['splash','landing','login','app'].forEach(id=>document.getElementById(id)?.classList.add('hide'));document.body.classList.add('staffOpen');root().classList.add('staffPublic');if(!attendance&&window.NayadApplications){await window.NayadApplications.landing();return true;}const token=new URLSearchParams(location.search).get('tsag'),device=localStorage.getItem(publicKey(token));if(device){const {data,error}=await sb().rpc('staff_employee_status',{p_store_token:token,p_device_token:device});if(!error&&data&&!data.error){state.publicData=data;renderPublic();return true;}localStorage.removeItem(publicKey(token));}renderPublicLogin();return true;}
  function brand(){return '<div class="staffBrand">NA<i>Y</i>AD</div>';}
  function renderPublicLogin(error=''){root().innerHTML=`<div class="staffShell">${brand()}<div class="staffLogin"><h1>Цаг бүртгэл</h1><p class="staffHint">Анхны удаа утасны дугаар, түр PIN-ээ оруулна.</p>${error?`<div class="staffError">${esc(error)}</div>`:''}<div class="staffForm"><label>Утасны дугаар</label><input id="staffPublicPhone" inputmode="numeric" maxlength="8"><label>PIN код</label><input id="staffPublicPin" type="password" inputmode="numeric" maxlength="6"><button class="staffSave" onclick="NayadStaff.signIn()">ҮРГЭЛЖЛҮҮЛЭХ</button></div></div></div>`;}
  async function signIn(){const token=new URLSearchParams(location.search).get('tsag'),phone=document.getElementById('staffPublicPhone').value,pin=document.getElementById('staffPublicPin').value;const {data,error}=await sb().rpc('staff_employee_sign_in',{p_store_token:token,p_phone:phone,p_pin:pin});if(error||data?.error)return renderPublicLogin(data?.error||error?.message||'Нэвтэрсэнгүй.');localStorage.setItem(publicKey(token),data.device_token);delete data.device_token;state.publicData=data;renderPublic();}
  function renderPublic(){window.NayadHub?.stop();clearInterval(state.timer);const d=state.publicData||{},active=d.clock_in&&!d.clock_out,finished=d.clock_out;root().innerHTML=`<div class="staffShell">${brand()}<div class="staffStore">${window.NayadApplications?.icon||''} ${esc(d.store_name||'Дэлгүүр')}</div><div class="staffAvatar" style="margin:15px auto;width:58px;height:58px">${esc((d.employee_name||'А').slice(0,1))}</div><h2><button class="staffProfileLink" onclick="NayadHub.profile()">Сайн байна уу, ${esc(d.employee_name||'')} ✎</button></h2><div class="staffToolbar"><button onclick="NayadHub.profile()">Миний мэдээлэл</button><button class="primaryMini" onclick="NayadHub.list()">Чат</button></div><div id="staffProfileReminder"></div><button class="selfLink selfHoursLink" onclick="NayadSelf.hours()">Миний цаг, цалин →</button><div>${esc(d.work_date||'')}</div><div id="staffLiveClock" class="staffClock">${active?duration(d.worked_seconds):new Intl.DateTimeFormat('mn-MN',{hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false,timeZone:'Asia/Ulaanbaatar'}).format(new Date())}</div><div class="staffPlace">⌖ Байршлыг товч дарахад шалгана</div><button class="staffPublicBtn in" ${active||finished?'disabled':''} onclick="NayadStaff.clock('in')">⇥ Ажилдаа ирлээ</button><button class="staffPublicBtn out" ${!active?'disabled':''} onclick="NayadStaff.clock('out')">⇥ Ажлаас гарлаа</button><div class="staffToday"><b>Өнөөдрийн бүртгэл</b><small>${d.clock_in?`Ирсэн ${time(d.clock_in)} · Гарсан ${time(d.clock_out)} · ${duration(d.worked_seconds)}`:'Одоогоор бүртгэлгүй'}</small><div class="staffDivider"></div><b>Энэ сарын баталсан цаг</b><small>${duration(d.month_seconds)}</small></div></div>`;window.NayadHub?.publicAvatar();window.NayadSelf?.reminder();if(active){let seconds=Number(d.worked_seconds)||0;state.timer=setInterval(()=>{seconds++;const el=document.getElementById('staffLiveClock');if(el)el.textContent=duration(seconds);},1000);}}
  async function clock(action){try{const p=await position(),token=new URLSearchParams(location.search).get('tsag'),device=localStorage.getItem(publicKey(token));const {data,error}=await sb().rpc('staff_employee_clock',{p_store_token:token,p_device_token:device,p_action:action,p_lat:p.coords.latitude,p_lng:p.coords.longitude,p_accuracy:p.coords.accuracy});if(error)throw error;state.publicData=data;renderPublic();}catch(error){window.alert(error.message||'Цаг бүртгэсэнгүй.');}}
  // The shortcut belongs to the viewport, not the scrolling supplier list.
  function installChatShortcut(){
    const app=document.getElementById('app'),nav=app?.querySelector('.bottom');
    if(!app||!nav||isAttendanceRoute()||document.getElementById('staffChatShortcut'))return;
    document.head.insertAdjacentHTML('beforeend',`<style>
      #staffChatShortcut{position:fixed;right:max(18px,env(safe-area-inset-right));bottom:120px;z-index:12;width:54px;height:54px;padding:0;border:0;border-radius:50%;background:#ffc107;color:#171717;display:grid;place-items:center;box-shadow:0 4px 14px #0002;cursor:pointer;touch-action:manipulation}
      #staffChatShortcut[hidden],body.staffOpen #staffChatShortcut{display:none!important}
      #staffChatShortcut svg{width:27px;height:27px}
      #staffChatShortcut:focus-visible{outline:3px solid #171717;outline-offset:4px}
    </style>`);
    const button=document.createElement('button');button.id='staffChatShortcut';button.type='button';button.hidden=true;
    button.setAttribute('aria-label','Ажилчидтай чатлах');button.title='Ажилчидтай чатлах';
    button.innerHTML='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M20 11.5a8 8 0 0 1-8 8 9 9 0 0 1-3.5-.7L4 20l1.2-4.5a8 8 0 1 1 14.8-4Z"/><circle cx="8" cy="11.5" r=".8" fill="currentColor" stroke="none"/><circle cx="12" cy="11.5" r=".8" fill="currentColor" stroke="none"/><circle cx="16" cy="11.5" r=".8" fill="currentColor" stroke="none"/></svg>';
    button.addEventListener('click',async()=>{
      if(!storeId())return window.toast?.('Дэлгүүрээ сонгоно уу.');
      if(button.disabled)return;button.disabled=true;
      try{install();document.body.classList.add('staffOpen');root();await window.NayadHub.list();}
      catch(error){close();window.toast?.(error.message||'Чат нээгдсэнгүй. Дахин оролдоно уу.');}
      finally{button.disabled=false;}
    });
    document.body.appendChild(button);
    function update(){
      button.hidden=!window.__nayadCan?.('staff','edit')||!app.getClientRects().length||getComputedStyle(app).display==='none'||!nav.querySelector('[data-page="home"].active');
      const rect=nav.getBoundingClientRect();
      button.style.bottom=rect.top>innerHeight/2?Math.max(18,innerHeight-rect.top+18)+'px':'max(24px, env(safe-area-inset-bottom))';
    }
    new MutationObserver(update).observe(app,{attributes:true,childList:true,subtree:true,attributeFilter:['class','hidden','style']});
    new ResizeObserver(update).observe(nav);window.addEventListener('resize',update);update();
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',installChatShortcut);else installChatShortcut();
